            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0xD7A37330CC7F35EFULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x196FDD63DCA86583ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x46BDF38C9C3A857BULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0xA672BDEC5F3DAF32ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xF5D42F3D55099411ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x9C75FB2E9A6293D3ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xA1F2FBDCB06F3D83ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x7731EDD3184AF5AAULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 22U)) & S_SALT1];
