            //
            aWandererI = aWandererI + (((RotL64(aPrevious, 21U) + aOrbiterG) + RotL64(aOrbiterI, 3U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aCross, 35U) + RotL64(aOrbiterI, 35U)) + aOrbiterK);
            aWandererK = aWandererK + ((RotL64(aScatter, 3U) + RotL64(aOrbiterF, 42U)) + aOrbiterD);
            aWandererD = aWandererD ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterF, 23U)) + aOrbiterI);
