            aWandererC = aWandererC ^ (((RotL64(aPrevious, 29U) + aOrbiterD) + RotL64(aOrbiterA, 11U)) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 44U) + aOrbiterG) + RotL64(aOrbiterD, 29U)) + RotL64(aCarry, 37U));
