            //
            aOrbiterH = ((aWandererE + RotL64(aPrevious, 43U)) + RotL64(aCarry, 5U)) + 0x2991ABD556A0DB35ULL;
            aOrbiterD = (aWandererJ + RotL64(aScatter, 28U)) + 0xC3CDE3271A5E46BCULL;
            aOrbiterI = ((aWandererA + RotL64(aIngress, 3U)) + 0x8534DC088999784BULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aCross, 37U)) + 0x64944CB5563491C4ULL;
            aOrbiterJ = (aWandererD + RotL64(aPrevious, 51U)) + 0x896E8510D28D9E88ULL;
            aOrbiterB = ((aWandererF + RotL64(aScatter, 57U)) + RotL64(aCarry, 53U)) + 0x96C9FC234B5842BDULL;
            aOrbiterE = (((aWandererG + RotL64(aCross, 13U)) + RotL64(aCarry, 41U)) + 0xBE3E09CA4CD3DB06ULL) + aTwistOrbiterAssignSaltF[((aIndex + 29U)) & S_SALT1];
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0xC29982DE10EE9D37ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0xE362AEC531326B8DULL;
            aOrbiterI = RotL64((aOrbiterI * 0xFC932E60A78BE25DULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xF271F31449BADAF2ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0xF01A0DE86F9D9AFCULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x07C091F9EED31D7BULL), 21U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0xE6BF7DF112E02A90ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 12U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x77A7D545E9DE64DBULL;
            aOrbiterH = RotL64((aOrbiterH * 0xD329131D230C2A05ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xA317C6BEDA57D9EBULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x7D550457C84C8556ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4E1DC54C1B2D1025ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x27A878F1D1FD77AFULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x29238F18F1F7D5BDULL;
            aOrbiterD = RotL64((aOrbiterD * 0x0F1871986855454DULL), 53U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xE3C9F65D6372AE42ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0xA6EA913B242B60E1ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 7U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x8813AD49217EBAE9ULL), 3U);
            //
