            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x3942F29A02D2BE7CULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0x8248A14A101DD9ADULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 19U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x0C9CA3981E2A0B59ULL), 29U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x53D19496919F3A25ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xCC3E42FD44508471ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0526FCA837A462EFULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xE258B4588F4FA223ULL;
