            aOrbiterA = (aWandererE + RotL64(aPrevious, 29U)) + 0xF10F90989A0647E2ULL;
            aOrbiterD = ((aWandererA + RotL64(aScatter, 53U)) + 0x4A36CE9630304711ULL) + aTwistOrbiterAssignSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aPrevious, 11U)) + 0x81F2FDC3C137DC1DULL) + aTwistOrbiterAssignSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterK = (aWandererK + RotL64(aCross, 35U)) + 0xAF95F5115CBD14F2ULL;
