            //
            aIngress = (RotL64(aIceLaneA[((aIndex + 2461U)) & S_BLOCK1], 19U) ^ RotL64(aIceLaneB[((aIndex + 1305U)) & S_BLOCK1], 50U));
            aIngress ^= (RotL64(aHeartLaneA[((aIndex + 4349U)) & S_BLOCK1], 11U) ^ RotL64(aSoilLaneA[((S_BLOCK1 - aIndex + 7258U)) & S_BLOCK1], 3U));
