            aOrbiterC = ((aWandererE + RotL64(aIngress, 51U)) + RotL64(aCarry, 35U)) + 0xD75422CEFE887384ULL;
            aOrbiterA = (((aWandererA + RotL64(aCross, 3U)) + RotL64(aCarry, 47U)) + 0x244A9EE311906E9AULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
