            //
            aWandererF = aWandererF + ((RotL64(aPrevious, 27U) + aOrbiterD) + RotL64(aOrbiterI, 3U));
            aWandererA = aWandererA ^ ((RotL64(aScatter, 60U) + RotL64(aOrbiterE, 35U)) + aOrbiterA);
