            aWandererD = aWandererD ^ ((RotL64(aCross, 37U) + RotL64(aOrbiterJ, 29U)) + aOrbiterG);
            aWandererE = aWandererE + ((RotL64(aScatter, 11U) + RotL64(aOrbiterA, 54U)) + aOrbiterK);
            aWandererG = aWandererG ^ ((RotL64(aCross, 47U) + aOrbiterF) + RotL64(aOrbiterG, 39U));
            aWandererB = aWandererB + (((RotL64(aPrevious, 51U) + aOrbiterD) + RotL64(aOrbiterE, 21U)) + RotL64(aCarry, 41U));
            //
            aCarry = aCarry + (RotL64(aWandererK, 54U) ^ aWandererJ);
            aCarry = aCarry + (aWandererF ^ RotL64(aWandererD, 57U));
