            aOrbiterH = ((aWandererG + RotL64(aPrevious, 3U)) + 0x5192B0D6F4C21925ULL) + aTwistOrbiterAssignSaltA[((aIndex + 28U)) & S_SALT1];
            aOrbiterA = (aWandererI + RotL64(aScatter, 11U)) + 0x4FE6CF2D8472D150ULL;
            aOrbiterG = ((aWandererE + RotL64(aCross, 58U)) + RotL64(aCarry, 19U)) + 0x78B14ED0E0326B6BULL;
            aOrbiterB = ((aWandererC + RotL64(aIngress, 41U)) + 0xCE45A843441B8DC0ULL) + aTwistOrbiterAssignSaltB[((aIndex + 22U)) & S_SALT1];
            aOrbiterC = (aWandererJ + RotL64(aPrevious, 19U)) + 0x9A60AFB283AADB85ULL;
            aOrbiterF = ((aWandererA + RotL64(aScatter, 27U)) + RotL64(aCarry, 5U)) + 0x099B98B4319BE0E5ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xF5327B2DF38DB1D5ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0xF5169AC5CCBCCEF1ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
