            aOrbiterH = ((aWandererD + RotL64(aCross, 53U)) + 0x9798EBCA2F81FAC5ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterD = ((aWandererF + RotL64(aScatter, 19U)) + RotL64(aCarry, 11U)) + 0xABB4764D27A31F9DULL;
            aOrbiterC = (aWandererB + RotL64(aPrevious, 26U)) + 0xC9F4618C347C23A7ULL;
            aOrbiterK = ((aWandererC + RotL64(aIngress, 35U)) + 0xE572596B08991E42ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterI = (aWandererA + RotL64(aPrevious, 5U)) + 0xAF40798F93126812ULL;
            aOrbiterG = ((aWandererG + RotL64(aCross, 47U)) + RotL64(aCarry, 23U)) + 0x028C44473725390AULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xCFA4F3472AC5D3DEULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x2537A39D0D4BE753ULL;
