            aWandererA = aWandererA ^ (((RotL64(aCross, 51U) + aOrbiterE) + RotL64(aOrbiterK, 23U)) + aKeyRotateWandererUpdateSaltF[((aIndex + 15U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 43U) + aOrbiterE) + RotL64(aOrbiterC, 37U)) + RotL64(aCarry, 27U)) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 11U)) & S_SALT1]);
