            aOrbiterF = ((aWandererK + RotL64(aIngress, 5U)) + RotL64(aCarry, 37U)) + 0x8E15839E8E52AEBDULL;
            aOrbiterI = (((aWandererB + RotL64(aPrevious, 41U)) + RotL64(aCarry, 5U)) + 0x2DF41664CA35D9C6ULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 15U)) & S_SALT1];
            aOrbiterD = ((aWandererI + RotL64(aScatter, 35U)) + 0xEAAF693721CAABD5ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
