            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x4B02703306477242ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 7U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x1628C3C4CAB0D6C8ULL;
