            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x57DBCFA51E15809AULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 6U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0xAE24049DFBA311C5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xB28DED9932CA56B3ULL), 47U);
