            aCross ^= (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 16U)) & S_BLOCK1], 27U) ^ RotL64(aPlasmaLaneB[((aIndex + 6750U)) & S_BLOCK1], 56U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aPrevious, 23U) + RotL64(aCarry, 11U)) + (RotL64(aIngress, 36U) ^ RotL64(aCross, 51U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterK = (aWandererJ + RotL64(aCross, 13U)) + 0x5143D4F78741CE1CULL;
            aOrbiterF = (aWandererH + RotL64(aIngress, 39U)) + 0x345131347905E470ULL;
            aOrbiterA = (aWandererF + RotL64(aPrevious, 3U)) + 0x2B18625AE9CE8A9CULL;
            aOrbiterJ = ((aWandererE + RotL64(aScatter, 10U)) + RotL64(aCarry, 13U)) + 0xDF1B7E7B2AAB9915ULL;
            aOrbiterI = ((aWandererA + RotL64(aPrevious, 35U)) + RotL64(aCarry, 19U)) + 0xFB755BFA2908DA09ULL;
            aOrbiterG = ((aWandererD + RotL64(aCross, 29U)) + 0x088EC42AED30F6D7ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterC = ((aWandererG + RotL64(aIngress, 41U)) + 0x932C060333E7ACE7ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 21U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aScatter, 6U)) + 0xB15CA2BF7545875DULL;
            aOrbiterH = (aWandererC + RotL64(aCross, 53U)) + 0xB4B66132A1CDFD3FULL;
            aOrbiterD = (aWandererI + RotL64(aScatter, 37U)) + 0x7D7C3A758B6340B5ULL;
            aOrbiterE = ((aWandererB + RotL64(aIngress, 47U)) + RotL64(aCarry, 3U)) + 0xF033F8A861EBC0D4ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x2BD4BF65F7D0F82AULL;
