            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0x99252869FC14C898ULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x520842A74AF4BAF5ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xB3F479076D856CBFULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x4109D31BEC3CED28ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x1EF62596DB62F0C4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x60CD7E3DDCBC475BULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0xD440C30EC67075A9ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x57BA7C656DA17F0BULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8BA4387EBDADE935ULL), 23U);
            //
