            aWandererE = aWandererE ^ ((RotL64(aCross, 27U) + aOrbiterK) + RotL64(aOrbiterB, 12U));
            aWandererG = aWandererG + ((RotL64(aScatter, 51U) + aOrbiterC) + RotL64(aOrbiterE, 43U));
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 6U) + RotL64(aOrbiterC, 37U)) + aOrbiterF) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 12U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererB, 48U));
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererD, 27U));
