            aOrbiterG = (aWandererC + RotL64(aIngress, 39U)) + 0x196283E9E35512BFULL;
            aOrbiterI = (aWandererJ + RotL64(aCross, 53U)) + 0xEE26E0FA6378B5A3ULL;
            aOrbiterD = ((aWandererA + RotL64(aScatter, 13U)) + 0xA4F375CB22F641E7ULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 12U)) & S_SALT1];
