            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0xAA1288E38C6C1A92ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 18U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x319CFCF74393A6DFULL;
