            aOrbiterI = RotL64((aOrbiterI * 0x7EB956D0EBC7E615ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xAA6497F771A6B275ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0x858A0B7488297E34ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x3F871738C36B3C7FULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x1320AB7650233F04ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xB447A2CF8D6F0889ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2870D22DEF445481ULL), 23U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x76620CF0690D5F58ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0x8383255C42082214ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xDAA27F28EA5DB4C7ULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x5A0961B37CBBDC60ULL;
