            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x15D630DE96EB6627ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0xCE89D9C046A70501ULL;
