            aCross = (RotL64(aVaporLaneC[((S_BLOCK1 - aIndex + 7006U)) & S_BLOCK1], 23U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 7760U)) & S_BLOCK1], 14U));
            aCross ^= (RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 3288U)) & S_BLOCK1], 51U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 5614U)) & S_BLOCK1], 35U));
