            aOrbiterH = ((aWandererB + RotL64(aScatter, 27U)) + RotL64(aCarry, 19U)) + 0xE4AAAC5F17AD8C94ULL;
            aOrbiterA = (aWandererC + RotL64(aPrevious, 13U)) + 0xD82527F14B4CD785ULL;
            aOrbiterK = ((aWandererG + RotL64(aIngress, 19U)) + RotL64(aCarry, 51U)) + 0xA4DDB1AD463BAB4CULL;
