            aOrbiterE = (((aWandererD + RotL64(aCross, 43U)) + RotL64(aCarry, 35U)) + 0xB8C6D53F97F58B4EULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
