            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x626C701371F863B4ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x919AE1AE91405096ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xA4D32F047260BB3FULL), 35U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x3B58F7643B3EE5CCULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x7BC792DAA536B4C1ULL;
