            aCross = (RotL64(aCelestialLaneA[((S_BLOCK1 - aIndex + 13809U)) & S_BLOCK1], 5U) ^ RotL64(aCelestialLaneD[((S_BLOCK1 - aIndex + 9417U)) & S_BLOCK1], 13U));
